// === Tab: mySketch.js ===
// ── Rainbow color name → HSB hue mapping ─────────────────────────────
const COLOR_MAP = {
  red:    0,
  orange: 25,
  yellow: 58,
  green:  120,
  blue:   230,
  indigo: 270,
  violet: 300,
};

// Default hues per particle type (sub / bass / mid / treble / presence)
const DEFAULT_HUE_BY_TYPE = [230, 180, 120, 60, 330];

let forcedHue = null;   // null = use per-type colours
let badgeTimeout = null;

const badge = document.getElementById('color-badge'); // may be null if element not in HTML

function setForcedHue(name, hue) {
  forcedHue = hue;
  if (badge) {
    badge.style.background = `hsl(${hue}, 90%, 55%)`;
    badge.style.color = (hue >= 50 && hue <= 70) ? '#000' : '#fff';
    badge.textContent = name.toUpperCase();
    badge.classList.add('visible');
  }
  clearTimeout(badgeTimeout);
  badgeTimeout = setTimeout(() => {
    forcedHue = null;
    if (badge) badge.classList.remove('visible');
  }, 5000);
}

// ── Continuous Speech Recognition ─────────────────────────────────────
function startSpeech() {
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SpeechRecognition) {
    console.warn('Speech Recognition not supported in this browser.');
    return;
  }
  const rec = new SpeechRecognition();
  rec.lang = 'en-US';
  rec.continuous = true;
  rec.interimResults = true;

  rec.onresult = (e) => {
    for (let i = e.resultIndex; i < e.results.length; i++) {
      const transcript = e.results[i][0].transcript.toLowerCase();
      for (const [name, hue] of Object.entries(COLOR_MAP)) {
        if (transcript.includes(name)) {
          setForcedHue(name, hue);
          break;
        }
      }
    }
  };
  rec.onend = () => rec.start(); // keep alive automatically
  rec.start();
}

// ── p5 sketch ──────────────────────────────────────────────────────────
let mic, fft;
let particles = [];
const NUM_PARTICLES = 4000;
let zOffset = 0;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);
  mic = new p5.AudioIn();
  fft = new p5.FFT(0.9, 1024);
  fft.setInput(mic);
  for (let i = 0; i < NUM_PARTICLES; i++) {
    particles.push(new Particle());
  }
}

function draw() {
  background(0, 0, 0, 5);
  fft.analyze();
  let subBass  = fft.getEnergy(20, 60);
  let bass     = fft.getEnergy(60, 250);
  let mid      = fft.getEnergy(250, 2000);
  let treble   = fft.getEnergy(2000, 6000);
  let presence = fft.getEnergy(6000, 12000);
  zOffset += 0.01;
  for (let p of particles) {
    p.update(subBass, bass, mid, treble, presence);
    p.display();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

// ── Particle class ─────────────────────────────────────────────────────
class Particle {
  constructor() {
    this.init();
  }

  init() {
    this.pos   = createVector(random(width), random(height));
    this.vel   = createVector(0, 0);
    this.type  = floor(random(5)); // 0=sub 1=bass 2=mid 3=treble 4=presence
    this.hue   = DEFAULT_HUE_BY_TYPE[this.type];
    this.alpha = 100;
    this.bri   = 40;
  }

  update(subBass, bass, mid, treble, presence) {
    // Noise-based fluid motion
    let n     = noise(this.pos.x * 0.002, this.pos.y * 0.002, zOffset);
    let angle = TAU * n;
    let force = p5.Vector.fromAngle(angle);
    force.mult(0.5);
    this.vel.add(force);
    this.vel.limit(2);
    this.pos.add(this.vel);

    // All particles use the spoken color — no frequency-based hue
    this.hue   = forcedHue !== null ? forcedHue : DEFAULT_HUE_BY_TYPE[this.type];
    this.alpha = 80;
    this.bri   = 80;

    // Wrap back on screen exit
    if (this.pos.x < -50 || this.pos.x > width  + 50 ||
        this.pos.y < -50 || this.pos.y > height + 50) {
      this.init();
    }
  }

  display() {
    noStroke();
    fill(this.hue, 80, this.bri, this.alpha);
    ellipse(this.pos.x, this.pos.y, 4, 4);
  }
}

// ── Start button: unlocks AudioContext + mic + speech ──────────────────
// Mic + speech start — works with or without a #start-btn in your HTML
async function startExperience() {
  if (typeof userStartAudio === 'function') await userStartAudio();
  mic.start();
  fft.setInput(mic);
  startSpeech();
}

const startBtn = document.getElementById('start-btn');
if (startBtn) {
  startBtn.addEventListener('click', function() {
    this.remove();
    startExperience();
  });
} else {
  // No button found — start automatically on first user interaction
  document.addEventListener('click', function handler() {
    document.removeEventListener('click', handler);
    startExperience();
  }, { once: true });
}

